import { test, expect } from '@playwright/test';

test.describe('Table Empty State Illustration', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should display empty state illustration when table has no data', async ({ page }) => {
    // Verify empty state illustration is visible
    const emptyStateEl = page.getByRole('region', { name: /no data/i });
    await expect(emptyStateEl).toBeVisible();

    // Verify empty state message is displayed
    const emptyMessage = page.getByText(/no data found/i);
    await expect(emptyMessage).toBeVisible();

    // Verify table header is visible
    const tableHeader = page.getByRole('heading', { name: /table headers/i });
    await expect(tableHeader).toBeVisible();

    // Verify table body is empty
    const tableBody = page.getByRole('tbody');
    await expect(tableBody).toBeEmpty();

    // Verify pagination controls are visible
    const pageLinks = page.getByRole('link', { name: /page/i });
    await expect(pageLinks).toBeVisible();

    // Verify no data indicator is visible
    const noDataIndicator = page.getByText(/no data/i);
    await expect(noDataIndicator).toBeVisible();
  });

  test('should handle loading state when table is empty', async ({ page }) => {
    // Verify empty state illustration is visible
    const emptyStateEl = page.getByRole('region', { name: /no data/i });
    await expect(emptyStateEl).toBeVisible();

    // Verify empty state message is displayed
    const emptyMessage = page.getByText(/no data found/i);
    await expect(emptyMessage).toBeVisible();

    // Verify table header is visible
    const tableHeader = page.getByRole('heading', { name: /table headers/i });
    await expect(tableHeader).toBeVisible();

    // Verify table body is empty
    const tableBody = page.getByRole('tbody');
    await expect(tableBody).toBeEmpty();

    // Verify loading indicator is visible
    const loadingIndicator = page.getByText(/loading/i);
    await expect(loadingIndicator).toBeVisible();

    // Verify pagination controls are visible
    const pageLinks = page.getByRole('link', { name: /page/i });
    await expect(pageLinks).toBeVisible();

    // Verify no data indicator is visible
    const noDataIndicator = page.getByText(/no data/i);
    await expect(noDataIndicator).toBeVisible();

    // Verify empty state illustration disappears when data is loaded
    const dataRows = page.getByRole('row', { name: /data row/i });
    await expect(dataRows).not.toBeVisible();

    // Verify empty state message disappears
    const emptyMessage = page.getByText(/no data found/i);
    await expect(emptyMessage).not.toBeVisible();

    // Verify table body now contains data
    const tableBody = page.getByRole('tbody');
    await expect(tableBody).toHaveCount(1);

    // Verify loading indicator is gone
    const loadingIndicator = page.getByText(/loading/i);
    await expect(loadingIndicator).not.toBeVisible();
  });
});
